"""THM AI1 d4 questions. Defender/assessor perspective: recognise, classify, map, defend, report."""

_n = [0]
def _id():
    _n[0] += 1
    return f"thm-ai1.d4.q{_n[0]:03d}"

def _base(lesson, diff, typ, case=None):
    return {"id": _id(), "lesson": f"thm-ai1.d4.{lesson}", "objective": "d4." + lesson[0], "difficulty": diff, "type": typ, "case": case}

def S(lesson, diff, stem, options, ans, explain, case=None):
    return {**_base(lesson, diff, "single", case), "stem": stem, "options": options, "answer": [ans], "explain": explain}

def M(lesson, diff, stem, options, ans, explain, case=None):
    return {**_base(lesson, diff, "multi", case), "stem": stem, "options": options, "answer": sorted(ans), "explain": explain}

def YN(lesson, diff, stem, sts, explain, case=None):
    return {**_base(lesson, diff, "yesno", case), "stem": stem, "statements": [{"s": s, "a": a} for s, a in sts], "explain": explain}

def O(lesson, diff, stem, steps, explain):
    return {**_base(lesson, diff, "order"), "stem": stem, "options": steps, "explain": explain}

def C(lesson, diff, stem, code, options, ans, explain):
    return {**_base(lesson, diff, "complete"), "stem": stem, "code": code, "options": options, "answer": [ans], "explain": explain}

